import 'package:flutter/material.dart'; class CustomTextField extends StatelessWidget { final TextEditingController controller; final String label; final bool obscure; const CustomTextField({super.key,required this.controller,required this.label,this.obscure=false}); @override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:TextField(controller:controller,obscureText:obscure,decoration:InputDecoration(labelText:label))); }